<?php $titulo='Equipamentos'; $modulo='equipamentos'; ?>
<div class="page-head"><div><h4>Equipamentos</h4><p class="text-muted mb-0 small">Inventário coletado de leases DHCP, vizinhos de rede, sessões e acessos do Squid.</p></div>
<?php if(pode_editar()):?><div class="d-flex flex-wrap gap-2 align-items-center"><span class="small text-muted"><span id="qtdSel">0</span> selecionado(s) — ação em lote com prévia:</span>
<button class="btn btn-sm btn-primary" data-gw-acao="alterar_grupo" data-gw-selecao=".sel-eq"><i class="bi bi-people"></i> Alterar grupo</button>
<button class="btn btn-sm btn-primary" data-gw-acao="liberar_temporario" data-gw-selecao=".sel-eq"><i class="bi bi-clock-history"></i> Liberar temporário</button>
<button class="btn btn-sm btn-danger" data-gw-acao="bloquear" data-gw-selecao=".sel-eq"><i class="bi bi-slash-circle"></i> Bloquear</button></div><?php endif;?></div><div class="card"><div class="table-responsive" tabindex="0" role="region" aria-label="Inventário de equipamentos"><table class="table table-sm table-hover align-middle mb-0 small"><thead class="table-light"><tr><?php if(pode_editar()):?><th style="width:32px"><input type="checkbox" id="selTodos" class="form-check-input" aria-label="Selecionar todos"></th><?php endif;?><th>Endereço</th><th>MAC</th><th>Hostname</th><th>Grupo / política</th><th>Sessão de usuário</th><th>Origem</th><th>Requisições 24h</th><th>Download HTTP 24h</th><th>Upload HTTP 24h</th><th>Último acesso</th><th class="acoes-sticky">Ações</th></tr></thead><tbody><?php foreach($equipamentos as $e):?><tr><?php if(pode_editar()):?><td><input type="checkbox" class="form-check-input sel-eq" value="<?=h($e['ip'])?>" aria-label="Selecionar <?=h($e['ip'])?>"></td><?php endif;?><td class="font-monospace fw-semibold"><?=h($e['ip'])?></td><td><?=h($e['mac']??'—')?></td><td><?=h($e['hostname']??'—')?></td><td><?=h($e['grupo_nome']??'Sem regra')?><?php if($e['expira_em']):?><div class="small text-warning">Regra expira <?=h($e['expira_em'])?></div><?php endif;?></td><td><?=h($e['email']??'—')?></td><td><?=h($e['origem'])?></td><td><?=number_format((int)$e['requisicoes'])?></td><td><?=formatar_bytes((int)$e['download_24h'])?></td><td><?=$e['upload_24h']===null?'sem dados':formatar_bytes((int)$e['upload_24h'])?></td><td><?=h($e['ultimo_acesso']??'—')?></td><td class="text-nowrap acoes-sticky"><a class="btn btn-sm btn-outline-primary" href="/equipamentos/ficha?ip=<?=rawurlencode($e['ip'])?>" title="Ficha completa"><i class="bi bi-pc-display-horizontal"></i></a> <?php if(pode_editar()):?><button class="btn btn-sm btn-outline-danger" data-gw-acao="bloquear" data-gw-ips="<?=h($e['ip'])?>" title="Bloquear"><i class="bi bi-slash-circle"></i></button> <button class="btn btn-sm btn-outline-success" data-gw-acao="liberar_temporario" data-gw-ips="<?=h($e['ip'])?>" title="Liberar temporariamente"><i class="bi bi-clock-history"></i></button><?php endif;?> <a class="btn btn-sm btn-outline-secondary" href="/internet/logs?ip=<?=rawurlencode($e['ip'])?>" title="Histórico de acesso"><i class="bi bi-clock-history"></i></a><?php if($e['email']):?> <a class="btn btn-sm btn-outline-warning" href="/internet" title="Usuários e sessões"><i class="bi bi-person-x"></i></a><?php endif;?></td></tr><?php endforeach;?><?php if(!$equipamentos):?><tr><td colspan="<?= pode_editar() ? 12 : 11 ?>" class="text-center text-muted py-4">Nenhum equipamento observado. O inventário será preenchido quando o Squid, o DHCP ou vizinhos da LAN fornecerem dados.</td></tr><?php endif;?></tbody></table></div></div>
<script>(()=>{const t=document.getElementById('selTodos'),q=document.getElementById('qtdSel');const b=()=>[...document.querySelectorAll('.sel-eq')];const u=()=>{if(q)q.textContent=b().filter(x=>x.checked).length};t?.addEventListener('change',()=>{b().forEach(x=>x.checked=t.checked);u()});document.addEventListener('change',e=>{if(e.target.classList?.contains('sel-eq'))u()});})();</script>
